input.command:
# Test if \x22 causes awk warnings locally
echo 'test line' | awk '$0 ~ /\x22/ { print "match" }' 2>&1
echo "---"
# And in a function similar to count_sketch_style_lines
echo 'Style requirements: <READABILITY_STYLE>.' | awk '
    $0 == "Style requirements: <READABILITY_STYLE>." {
        count++
        next
    }
    $0 ~ /\\nStyle requirements: <READABILITY_STYLE>\.\x22`$/ {
        count++
    }
    END {
        print count + 0
    }
' 2>&1

# Check if grep -E with em-dash produces stderr
orchestrator_style_re='^\*\*MANDATORY — READ ENTIRE FILE before [^:]+: `skills/design/references/readability-style\.md`\.\*\*$'
echo '**MANDATORY — READ ENTIRE FILE before composing: `skills/design/references/readability-style.md`.**' | grep -Ec "$orchestrator_style_re" 2>&1
echo "---"
# Check the step marker awk pass
check_file=$(mktemp)
printf '%s\n' '<!-- step:2b — fixture -->' '**MANDATORY — READ ENTIRE FILE before composing: `skills/design/references/readability-style.md`.**' '<!-- step:3b — fixture -->' > "$check_file"
awk -v step_id="2b" -v rel_path="skills/design/SKILL.md" -v style_re="$orchestrator_style_re" '
BEGIN { in_step = 0; count = 0; found_marker = 0 }
{
    if (match($0, "^<!-- step:" step_id "([[:space:]]|—)")) {
        in_step = 1; found_marker = 1; count = 0; next
    }
    if (in_step && match($0, "^<!-- step:")) {
        if (count < 1) { print "STEP_FAIL"; exit 1 }
        in_step = 0; count = 0
    }
    if (in_step && $0 ~ style_re) { count++ }
}
END {
    if (!found_marker) { print "NO_MARKER" > "/dev/stderr"; exit 1 }
    if (in_step && count < 1) { print "END_FAIL" > "/dev/stderr"; exit 1 }
}
' "$check_file" 2>&1
echo "awk_exit=$?"
rm -f "$check_file"
